// A shopping cart's state management, the way it grows naturally:
// one shared object, mutated from wherever, with "remember to update
// the UI" sprinkled by hand.

// Problem 1: global mutable state. ANY code can reach in and change
// ANYTHING, so when cart.items is mysteriously wrong, the suspect
// list is the entire codebase.
var state = {
  items: [],
  coupon: null,
};

// Problem 2: every mutation site must REMEMBER to call the right
// update functions. Forget one (see removeItem) and the UI silently
// drifts out of sync with the data.
function addItem(name, priceCents) {
  state.items.push({ name: name, priceCents: priceCents });
  renderCart();
  renderTotal();
}

function removeItem(name) {
  state.items = state.items.filter(function (i) { return i.name !== name; });
  renderCart();
  // ...forgot renderTotal(). The total now shows a deleted item.
}

function applyCoupon(code) {
  // Problem 3: business rules live at the mutation site. Is the
  // coupon valid? Every place that touches coupons re-decides,
  // and they disagree.
  if (code === "SAVE10") state.coupon = 0.9;
  renderTotal(); // forgot renderCart(), which shows the coupon badge
}

// Problem 4: no history, no way to answer "HOW did state end up like
// this?" — mutations leave no trace. (Project 39 solved undo with
// snapshots; here we can't even log changes, because nothing funnels
// them.)

function renderCart() {
  console.log("cart:", state.items.map(function (i) { return i.name; }).join(", ") || "(empty)");
}

function renderTotal() {
  var total = 0;
  for (var i = 0; i < state.items.length; i++) total += state.items[i].priceCents;
  if (state.coupon) total = Math.round(total * state.coupon);
  console.log("total:", (total / 100).toFixed(2), state.coupon ? "(coupon)" : "");
}

addItem("keyboard", 4900);
addItem("mouse", 2900);
applyCoupon("SAVE10");
removeItem("keyboard");
// total still includes the keyboard's discount math on the stale render:
renderTotal(); // manually patched here — that's the disease, not the cure

# 🏋️ Practice: Reactive State Store

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

For each exercise, create a scratch file (e.g. `practice.test.js`) inside `refactored/` and run it with `node --test 59-state-store/refactored/practice.test.js`. Exercises 2 and 3 edit `cart.js` — undo your edits (or keep a backup) when you're done.

## Exercises

### ⭐ 1. An `itemCount` selector (warm-up)
Write a new derived-data function `itemCount(state)` in the style of `totalCents`: it returns how many items are in the cart, computed fresh from state every call. Test it: after dispatching two `item/added` actions, `itemCount(store.getState())` must be `2`, and `itemCount(initialCart)` must be `0`.
What it practices: derived data is computed from state, never stored beside it.
Hint: it's a one-liner reading `state.items`.

### ⭐⭐ 2. A `coupon/removed` action (core)
Add a `coupon/removed` case to `cartReducer`. Removing a coupon returns a new state with `coupon: null` — but if there is no coupon to remove, return `state` itself (the *same reference*), just like an invalid coupon code does. Expected: after applying `SAVE10` then dispatching `{ type: 'coupon/removed' }`, `state.coupon` is `null` and `items` are untouched; and `cartReducer(initialCart, { type: 'coupon/removed' }) === initialCart` is `true`.
What it practices: extending the one brain, plus the same-reference "nothing changed" contract.
Hint: two branches — one spread, one `return state;`.

### ⭐⭐ 3. Reject duplicate item names (core)
Change the `'item/added'` case so that adding an item whose `name` already exists in the cart changes nothing — return the same state reference. Expected: dispatching `item/added` for `'kb'` twice leaves `items.length === 1`, and the reducer returns the exact same object for the second call (checkable with `===`).
What it practices: business rules live in the reducer, and no-ops return the same reference.
Hint: `state.items.some((i) => i.name === action.name)` before building anything new.

### ⭐⭐ 4. A `once(store, fn)` helper (core)
Write `once(store, fn)`: it subscribes `fn` so that it runs after the *next* state change only, then automatically unsubscribes itself. Expected: with `let calls = 0; once(store, () => calls++)`, dispatching three valid actions leaves `calls === 1`.
What it practices: the unsubscribe-handle contract, and closures that capture their own teardown.
Hint: `subscribe` returns the off-switch — call it *inside* the listener, before running `fn`.

### ⭐⭐⭐ 5. A validator middleware (challenge)
Write a middleware that refuses bad merchandise: any `item/added` action whose `priceCents` isn't a positive integer is swallowed — `next` is never called, so the reducer never sees it and subscribers are not notified. Expected: after dispatching `{ type: 'item/added', name: 'free', priceCents: -100 }`, `store.getState() === initialCart` (same reference!) and a subscribed counter is still `0`; a valid add afterwards works normally.
What it practices: the middleware onion — cross-cutting rules without touching store or reducer.
Hint: shape is `() => (next) => (action) => ...`; "swallow" means `return action` instead of `return next(action)`.

### ⭐⭐⭐ 6. Undo, as a higher-order reducer (challenge)
Write `undoable(reducer)`: it takes any reducer and returns a new reducer whose state has the shape `{ past: [], present }`. Normal actions push the old `present` onto `past` and store the new result; a `{ type: 'undo' }` action pops the last past state back into `present`; undo on an empty history is a safe no-op. Bonus rule: if the inner reducer returned the *same reference* (a no-op like an invalid coupon), don't pollute the history. Expected: add item (4900) → apply `SAVE10` → total is 4410; one `undo` → coupon gone, total 4900; second `undo` → empty cart; third `undo` → still empty, no crash.
What it practices: reducers are just functions — so they compose, and "state changes are data" makes undo almost free.
Hint: create the store with `createStore(undoable(cartReducer), { past: [], present: initialCart })`; read totals via `store.getState().present`.

## Solutions

### 1. `itemCount`
```js
export function itemCount(state) {
  return state.items.length;
}
```
WHY: Same principle as `totalCents` — derived data is a pure computation over state. A stored counter could drift out of sync with `items`; a computed one cannot go stale.

### 2. `coupon/removed`
```js
// in cartReducer's switch:
case 'coupon/removed':
  return state.coupon === null ? state : { ...state, coupon: null };
```
WHY: All coupon rules stay in the one tested brain. Returning `state` itself when there's nothing to remove keeps the project's "no change = same reference" contract, which makes no-ops detectable with a single `===` — the exact trick the invalid-coupon test relies on.

### 3. Duplicate names rejected
```js
case 'item/added':
  if (state.items.some((i) => i.name === action.name)) return state; // no-op
  return {
    ...state,
    items: [...state.items, { name: action.name, priceCents: action.priceCents }],
  };
```
WHY: In the original, this rule would have to be re-decided at every mutation site. In the reducer it exists exactly once, is pure, and is testable with two dispatches and one `===` — no store, no UI.

### 4. `once`
```js
function once(store, fn) {
  const off = store.subscribe(() => {
    off();  // tear down FIRST, so a dispatch inside fn can't re-trigger us
    fn();
  });
  return off;
}
```
WHY: This is the unsubscribe-handle contract (project 38) put to work: the listener closes over its own off-switch. It only works safely because `baseDispatch` notifies a *copy* of the listener set — deleting mid-notify can't break the loop.

### 5. Validator middleware
```js
const validator = () => (next) => (action) => {
  if (
    action.type === 'item/added' &&
    !(Number.isInteger(action.priceCents) && action.priceCents > 0)
  ) {
    return action; // refused: the reducer never sees it
  }
  return next(action);
};
const store = createStore(cartReducer, initialCart, [validator]);
```
WHY: Because actions are plain data flowing through one door, a gatekeeper is three lines of middleware — no edits to `store.js` or `cart.js`. Asserting `store.getState() === initialCart` afterwards reuses the same-reference fact: nothing was dispatched, so nothing changed and nobody re-rendered.

### 6. `undoable`
```js
function undoable(reducer) {
  return (state, action) => {
    if (action.type === 'undo') {
      return state.past.length === 0
        ? state
        : { past: state.past.slice(0, -1), present: state.past.at(-1) };
    }
    const next = reducer(state.present, action);
    return next === state.present
      ? state // inner no-op: keep history clean
      : { past: [...state.past, state.present], present: next };
  };
}

const store = createStore(undoable(cartReducer), { past: [], present: initialCart });
store.dispatch({ type: 'item/added', name: 'kb', priceCents: 4900 });
store.dispatch({ type: 'coupon/applied', code: 'SAVE10' });
// totalCents(store.getState().present) === 4410
store.dispatch({ type: 'undo' });
// coupon is null again, total 4900
store.dispatch({ type: 'undo' });
// items: [] — and further undos are safe no-ops
```
WHY: This is the README's promise ("you get undo almost for free") made concrete. Because the reducer is pure and every past state is an immutable snapshot, "history" is just an array of old references — no copying, no store changes. The same-reference check from exercise 2/3 pays off again: no-op actions are detected with `===` and never pollute the undo stack. (Verified by running it under Node.)

/**
 * The cart, rebuilt as a reducer: every business rule about carts
 * lives HERE, in one pure function, tested without a store or a UI.
 *
 * Immutability discipline: never state.x = ..., always build new
 * objects around unchanged pieces (project 26's no-mutation
 * contracts). Same references in = same data; new references = "this
 * part changed" — which is what makes cheap change-detection
 * possible downstream.
 */

export const initialCart = { items: [], coupon: null };

const VALID_COUPONS = { SAVE10: 0.9, SAVE25: 0.75 };

export function cartReducer(state = initialCart, action) {
  switch (action.type) {
    case 'item/added':
      return {
        ...state,
        items: [...state.items, { name: action.name, priceCents: action.priceCents }],
      };
    case 'item/removed':
      return {
        ...state,
        items: state.items.filter((i) => i.name !== action.name),
      };
    case 'coupon/applied':
      // THE rule about coupons, in exactly one place:
      return action.code in VALID_COUPONS
        ? { ...state, coupon: VALID_COUPONS[action.code] }
        : state;
    default:
      return state; // unknown actions change nothing (forward compat)
  }
}

/** Derived data is COMPUTED from state, never stored beside it. */
export function totalCents(state) {
  const subtotal = state.items.reduce((sum, i) => sum + i.priceCents, 0);
  return state.coupon ? Math.round(subtotal * state.coupon) : subtotal;
}

/**
 * createStore — a mini Redux/Zustand. Four ideas, ~40 lines:
 *
 *   1. State is READ-ONLY from outside. The only door in is
 *      dispatch(action) — so "how did state end up like this?"
 *      has an answer: the action log.
 *   2. A REDUCER decides: (state, action) -> NEW state. Pure,
 *      immutable, all business rules in one testable place.
 *   3. subscribe() gets notified after every change — rendering
 *      can't be forgotten at a mutation site, because there are
 *      no mutation sites.
 *   4. MIDDLEWARE wraps dispatch: logging, async, crash reporting —
 *      cross-cutting concerns without touching the reducer.
 */

export function createStore(reducer, initialState, middlewares = []) {
  let state = initialState;
  const listeners = new Set();
  let dispatching = false;

  function getState() {
    return state;
  }

  function subscribe(listener) {
    listeners.add(listener);
    return () => listeners.delete(listener); // project 38's contract
  }

  function baseDispatch(action) {
    if (action == null || typeof action.type !== 'string') {
      throw new TypeError('Actions must be objects with a string "type"');
    }
    // A reducer dispatching mid-reduce means state changed while we
    // were computing state from it. Refuse, loudly.
    if (dispatching) throw new Error('Reducers must not dispatch');

    dispatching = true;
    try {
      state = reducer(state, action);
    } finally {
      dispatching = false;
    }
    for (const listener of [...listeners]) listener(); // copy: 38's emit lesson
    return action;
  }

  // Build the middleware onion: each middleware receives the NEXT
  // dispatch and returns a wrapped one. [a, b] => a(b(baseDispatch)) —
  // a sees the action first, base last.
  const dispatch = middlewares
    .reduceRight((next, mw) => mw({ getState, dispatch: (a) => dispatch(a) })(next), baseDispatch);

  return { getState, dispatch, subscribe };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from './store.js';
import { cartReducer, initialCart, totalCents } from './cart.js';

// ---------- the reducer alone: pure business logic ------------------

test('reducer: add/remove items immutably', () => {
  const s1 = cartReducer(initialCart, { type: 'item/added', name: 'kb', priceCents: 4900 });
  const s2 = cartReducer(s1, { type: 'item/added', name: 'mouse', priceCents: 2900 });
  const s3 = cartReducer(s2, { type: 'item/removed', name: 'kb' });

  assert.deepEqual(s3.items.map((i) => i.name), ['mouse']);
  assert.deepEqual(initialCart.items, []); // originals untouched
  assert.deepEqual(s2.items.length, 2);
});

test('reducer: coupon rule lives in ONE place — invalid codes change nothing', () => {
  const valid = cartReducer(initialCart, { type: 'coupon/applied', code: 'SAVE10' });
  const invalid = cartReducer(initialCart, { type: 'coupon/applied', code: 'HAX' });
  assert.equal(valid.coupon, 0.9);
  assert.equal(invalid, initialCart); // same reference: nothing changed
});

test('derived data: total is computed, so it CANNOT go stale', () => {
  let s = initialCart;
  s = cartReducer(s, { type: 'item/added', name: 'kb', priceCents: 4900 });
  s = cartReducer(s, { type: 'item/added', name: 'mouse', priceCents: 2900 });
  s = cartReducer(s, { type: 'coupon/applied', code: 'SAVE10' });
  s = cartReducer(s, { type: 'item/removed', name: 'kb' });
  // The original showed a stale total here; a computed one can't:
  assert.equal(totalCents(s), Math.round(2900 * 0.9));
});

// ---------- the store: subscription mechanics ------------------------

test('subscribers are notified on every dispatch — rendering cannot be forgotten', () => {
  const store = createStore(cartReducer, initialCart);
  let renders = 0;
  store.subscribe(() => renders++);
  store.dispatch({ type: 'item/added', name: 'kb', priceCents: 100 });
  store.dispatch({ type: 'item/removed', name: 'kb' });
  assert.equal(renders, 2);
});

test('unsubscribe stops notifications (38\'s contract)', () => {
  const store = createStore(cartReducer, initialCart);
  let calls = 0;
  const off = store.subscribe(() => calls++);
  store.dispatch({ type: 'item/added', name: 'a', priceCents: 1 });
  off();
  store.dispatch({ type: 'item/added', name: 'b', priceCents: 1 });
  assert.equal(calls, 1);
});

test('dispatch validates actions', () => {
  const store = createStore(cartReducer, initialCart);
  assert.throws(() => store.dispatch(undefined), TypeError);
  assert.throws(() => store.dispatch({ noType: true }), TypeError);
});

// ---------- middleware: the onion ------------------------------------

test('middleware wraps dispatch in order: first middleware sees actions first', () => {
  const order = [];
  const tag = (name) => () => (next) => (action) => {
    order.push(name);
    return next(action);
  };
  const store = createStore(cartReducer, initialCart, [tag('logger'), tag('crash')]);
  store.dispatch({ type: 'item/added', name: 'kb', priceCents: 1 });
  assert.deepEqual(order, ['logger', 'crash']);
});

test('a logging middleware sees every action + the state after it', () => {
  const log = [];
  const logger = ({ getState }) => (next) => (action) => {
    const result = next(action);
    log.push({ type: action.type, count: getState().items.length });
    return result;
  };
  const store = createStore(cartReducer, initialCart, [logger]);
  store.dispatch({ type: 'item/added', name: 'kb', priceCents: 1 });
  store.dispatch({ type: 'item/removed', name: 'kb' });
  assert.deepEqual(log, [
    { type: 'item/added', count: 1 },
    { type: 'item/removed', count: 0 },
  ]);
});

test('a "thunk" middleware turns function-actions into async workflows', async () => {
  const thunk = ({ dispatch, getState }) => (next) => (action) =>
    typeof action === 'function' ? action(dispatch, getState) : next(action);

  const store = createStore(cartReducer, initialCart, [thunk]);
  await store.dispatch(async (dispatch) => {
    await new Promise((r) => setTimeout(r, 5)); // "fetch" the price
    dispatch({ type: 'item/added', name: 'kb', priceCents: 4900 });
  });
  assert.equal(totalCents(store.getState()), 4900);
});
